So, code outline:

#include <bits/stdc++.h>

using namespace std;

int main() {

    int n, k;

    scanf("%d %d", &n, &k);

    vector<int> a(n);

    for (int i=0; i<n; ++i) {

        scanf("%d", &a[i]);

    }

    vector<int> counts(1e6 + 2, 0); // since a[i] can be up to 1e6.

Wait, but 1e6 is 10^6, so 1e6+2 would be 1000002 elements. So perhaps initializing counts as a vector of 1e6+2 elements. But in C++, creating a vector of that size is possible. But 1e6+2 is 1,000,002 elements. Each is an int (4 bytes), so around 4MB. That's acceptable.

But another approach is to compute the maximum element in the array and create a counts array of that size. But that would require an O(n) pass first. However, given that the elements can be up to 1e6, it's better to preallocate 1e6+2. Because if the elements are up to 1e6, the counts array will cover all possibilities.

So proceed with vector<int> counts(1e6 + 2, 0);

Then, the sliding window code:

int left = 0;

int current_distinct = 0;

int max_len = 0;

int result_left = 0, result_right = 0;

for (int right = 0; right < n; ++right) {

    int num = a[right];

    if (counts[num] == 0) {

        current_distinct++;

    }

    counts[num]++;

    while (current_distinct > k) {

        int left_num = a[left];

        counts[left_num]--;

        if (counts[left_num] == 0) {

            current_distinct--;

        }

        left++;

    }

    // Now check if current window is better

    int current_len = right - left + 1;

    if (current_len > max_len) {

        max_len = current_len;

        result_left = left;

        result_right = right;

    }

}

