    int sum = 0;
    int max_k = min(x, y);
    for (int k = 0; k <= max_k; ++k) {
        int term = (long long)C(x, k) * C(y, k) % MOD;
        term = (long long)term * fact[k] % MOD;
        sum = (sum + term) % MOD;
    }
    return sum;
}

